import React, { useState } from "react";
import { NavLink, useNavigate } from "react-router-dom";
import axios from "axios";
import "./common.css";
import "./Form.css";

function Form() {
  const navigate = useNavigate();
  const [type, setType] = useState("DOOR_OPEN");
  const [zone, setZone] = useState("");
  const [responsible, setResponsible] = useState("");
  const [severity, setSeverity] = useState("LOW");
  const [comment, setComment] = useState("");

  const handleAdd = async () => {
    const newEvent = {
      type,
      zone: zone.trim() || "Не указано",
      responsible: responsible.trim() || "Не указан",
      severity,
      time: new Date().toLocaleString("ru-RU"),
      comment: comment.trim(),
    };

    await axios.post("http://localhost:5000/events", newEvent);
    navigate("/");
  };

  const handleClear = () => {
    setZone("");
    setResponsible("");
    setComment("");
  };

  return (
    <main className="form-page">
      <header className="form-page__header">
        <div className="form-page__headline">
          <h1 className="form-page__title">Новая запись журнала</h1>
          <NavLink className="btn btn--primary btn--link" to="/">
            На главную
          </NavLink>
        </div>
      </header>

      <section className="form-page__grid">
        <div className="card card--wide">
          <div className="form-page__layout">
            <div className="form-page__column">
              <label className="field">
                <span className="field__label">Тип события</span>
                <select
                  className="field__control"
                  value={type}
                  onChange={(event) => setType(event.target.value)}
                >
                  <option value="DOOR_OPEN">Открытие двери</option>
                  <option value="ACCESS_ATTEMPT">Попытка доступа</option>
                  <option value="ALARM">Срабатывание датчика</option>
                </select>
              </label>

              <label className="field">
                <span className="field__label">Зона/объект</span>
                <input
                  className="field__control"
                  type="text"
                  value={zone}
                  onChange={(event) => setZone(event.target.value)}
                />
              </label>

              <label className="field">
                <span className="field__label">Ответственный</span>
                <input
                  className="field__control"
                  type="text"
                  value={responsible}
                  onChange={(event) => setResponsible(event.target.value)}
                />
              </label>
            </div>

            <div className="form-page__column">
              <label className="field">
                <span className="field__label">Критичность</span>
                <select
                  className="field__control"
                  value={severity}
                  onChange={(event) => setSeverity(event.target.value)}
                >
                  <option value="LOW">Низкая</option>
                  <option value="MEDIUM">Средняя</option>
                  <option value="CRITICAL">Высокая</option>
                </select>
              </label>

              <label className="field">
                <span className="field__label">Комментарий</span>
                <textarea
                  className="field__control field__control--textarea"
                  value={comment}
                  onChange={(event) => setComment(event.target.value)}
                />
              </label>

              <div className="card__actions">
                <button className="btn btn--primary" onClick={handleAdd}>
                  Добавить событие
                </button>
                <button className="btn btn--ghost" onClick={handleClear}>
                  Очистить
                </button>
              </div>
            </div>
          </div>
        </div>
      </section>
    </main>
  );
}

export default Form;
